<style id="MCI_PREMIUM_HOMEPAGE_V2_BATCH1">
:root{--v2-navy:#071a35;--v2-blue:#0b2f58;--v2-green:#078a50;--v2-gold:#d8aa30;--v2-ice:#eef4f1;--v2-line:#d9e1df;--v2-serif:Georgia,"Times New Roman",serif}
.v2-utility{min-height:34px;padding:7px clamp(24px,5vw,76px);display:flex;align-items:center;justify-content:space-between;background:var(--v2-navy);color:#dbe6ef;font-size:12px;letter-spacing:.03em}.v2-utility div{display:flex;gap:26px}.v2-utility a{color:#fff;text-decoration:none}.v2-header{height:92px;background:#fff;position:sticky}.v2-header .brand{gap:14px}.v2-header .brand-logo{width:58px;height:58px}.v2-header .brand strong{font-family:var(--v2-serif);font-size:20px;color:var(--v2-navy)}.v2-header .brand small{margin-top:3px;color:#607182;font-size:9px;letter-spacing:1.35px}.v2-header nav{gap:24px}.v2-header nav a{font-size:13px;color:#304559}.v2-header .pill{border-radius:4px;background:var(--v2-green);padding:14px 18px}.v2-header .pill span{margin-left:9px}
.v2-hero{min-height:610px!important;padding:0!important;display:grid;grid-template-columns:minmax(0,.94fr) minmax(0,1.06fr);gap:0;background:#f5f8f6}.v2-hero .hero-copy{padding:clamp(58px,7vw,104px) clamp(34px,7vw,105px);align-self:center}.v2-overline,.v2-kicker{font-size:12px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:var(--v2-green)}.v2-hero h1{max-width:660px;margin:20px 0 25px;font-family:var(--v2-serif);font-size:clamp(52px,5.5vw,84px);line-height:.98;letter-spacing:-3.5px;color:var(--v2-navy)}.v2-hero h1 em{display:inline;color:var(--v2-green);font-style:italic;font-weight:500}.v2-hero .hero-copy>p{max-width:610px;font-size:17px;line-height:1.7;color:#42576a}.v2-hero .hero-copy .hi{font-size:14px;color:#687b89}.v2-hero .actions{margin:31px 0 36px}.v2-hero .primary,.v2-hero .secondary{border-radius:3px;padding:15px 20px;font-size:13px}.v2-hero .primary{background:var(--v2-green)}.v2-hero .secondary{border:1px solid #bdc9c5}.v2-hero .actions span{margin-left:12px}.v2-hero-note{display:flex;align-items:center;gap:14px;border-top:1px solid var(--v2-line);padding-top:22px}.v2-hero-note>span{width:8px;height:8px;border-radius:50%;background:var(--v2-gold);box-shadow:0 0 0 5px #d8aa3020}.v2-hero-note p,.v2-hero-note b,.v2-hero-note small{display:block;margin:0}.v2-hero-note b{font-size:13px;color:var(--v2-navy)}.v2-hero-note small{margin-top:4px;color:#75858f}.v2-hero .hero-media{height:100%!important;min-height:610px;position:relative;border-radius:0!important}.v2-hero .hero-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 58%,#04182db8)}.v2-hero .hero-media>img{height:100%!important;border-radius:0!important;box-shadow:none!important;object-position:center!important}.v2-image-caption{position:absolute;z-index:2;left:42px;right:42px;bottom:35px;padding-top:17px;border-top:1px solid #ffffff70;color:#fff}.v2-image-caption small,.v2-image-caption b{display:block}.v2-image-caption small{font-size:10px;letter-spacing:1.8px}.v2-image-caption b{margin-top:7px;font-family:var(--v2-serif);font-size:20px}.v2-trust{min-height:62px;background:var(--v2-navy);gap:28px;font-size:11px}.v2-trust i{width:4px;height:4px;border-radius:50%;background:var(--v2-gold)}
.v2-about{padding:105px clamp(24px,7vw,108px);display:grid;grid-template-columns:230px 1fr;gap:clamp(45px,8vw,130px);background:#fff}.v2-section-label{display:flex;gap:17px;align-items:flex-start;color:#6f7f88;font-size:12px;line-height:1.55;text-transform:uppercase;letter-spacing:.08em}.v2-section-label>span{color:var(--v2-green);font-weight:900}.v2-section-label p{margin:0}.v2-section-label b{color:#82918f;font-size:11px}.v2-about-copy{display:grid;grid-template-columns:1.18fr .82fr;gap:clamp(40px,7vw,100px)}.v2-lead{margin:0;font-family:var(--v2-serif);font-size:clamp(29px,3vw,44px);line-height:1.2;color:var(--v2-navy)}.v2-about-detail p{margin:0 0 30px;color:#526675;font-size:16px;line-height:1.8}.v2-about-detail a{display:inline-flex;gap:22px;padding-bottom:8px;border-bottom:2px solid var(--v2-green);color:var(--v2-navy);font-size:13px;font-weight:800;text-decoration:none}
.v2-institutions{padding:100px clamp(24px,7vw,108px);background:var(--v2-ice)}.v2-section-head{display:grid;grid-template-columns:1fr minmax(280px,440px);gap:60px;align-items:end;margin-bottom:55px}.v2-section-head h2{margin:16px 0 0;font-family:var(--v2-serif);font-size:clamp(43px,4.4vw,66px);line-height:1.03;letter-spacing:-2.5px;color:var(--v2-navy)}.v2-section-head h2 em{color:var(--v2-green);font-weight:500}.v2-section-head>p{margin:0;color:#5c6f79;font-size:16px;line-height:1.75}.v2-institution-grid{display:grid;grid-template-columns:repeat(12,1fr);border-top:1px solid #bfcac6}.v2-institution{grid-column:span 4;min-height:285px;padding:30px;border-right:1px solid #bfcac6;border-bottom:1px solid #bfcac6;display:flex;flex-direction:column;color:var(--v2-navy);text-decoration:none;transition:.25s}.v2-institution:nth-child(3){border-right:0}.v2-institution:nth-child(4),.v2-institution:nth-child(5){grid-column:span 6}.v2-institution:nth-child(5){border-right:0}.v2-institution:hover{background:#fff;transform:translateY(-4px);box-shadow:0 18px 35px #0b2f5814}.v2-institution>span{font-size:12px;color:var(--v2-green);font-weight:900}.v2-institution>div{margin:auto 0}.v2-institution small{font-size:10px;letter-spacing:1.5px;color:#788883}.v2-institution h3{margin:9px 0;font-family:var(--v2-serif);font-size:26px}.v2-institution p{max-width:330px;margin:0;color:#687a80;font-size:14px;line-height:1.65}.v2-institution>b{font-size:12px}.v2-institution.featured{background:var(--v2-navy);color:#fff}.v2-institution.featured p,.v2-institution.featured small{color:#b8c7ce}.v2-institution.featured>span{color:#efc75d}
.v2-impact{padding:54px clamp(24px,7vw,108px);display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border-bottom:1px solid var(--v2-line)}.v2-impact>div{display:flex;align-items:center;gap:18px;padding:13px 25px;border-right:1px solid var(--v2-line)}.v2-impact>div:last-child{border:0}.v2-impact strong{font-family:var(--v2-serif);font-size:42px;color:var(--v2-green)}.v2-impact span{font-size:12px;line-height:1.5;text-transform:uppercase;letter-spacing:.08em;color:#5e707b}
@media(max-width:1150px){.v2-header nav{gap:14px}.v2-header nav a{font-size:12px}.v2-hero{grid-template-columns:1fr 1fr}.v2-hero .hero-copy{padding:65px 42px}.v2-about{grid-template-columns:170px 1fr}.v2-about-copy{grid-template-columns:1fr}.v2-institution{grid-column:span 6}.v2-institution:nth-child(3){border-right:1px solid #bfcac6}.v2-institution:nth-child(even){border-right:0}.v2-institution:nth-child(5){grid-column:span 12}}
@media(max-width:900px){.v2-utility{display:none}.v2-header{height:76px}.v2-header .brand-logo{width:48px;height:48px}.v2-header .brand strong{font-size:17px}.v2-hero{grid-template-columns:1fr}.v2-hero .hero-copy{padding:62px 28px}.v2-hero .hero-media{min-height:430px}.v2-about{grid-template-columns:1fr;padding-top:75px;padding-bottom:75px}.v2-about-copy{gap:30px}.v2-section-head{grid-template-columns:1fr;gap:25px}.v2-impact{grid-template-columns:1fr 1fr}.v2-impact>div:nth-child(2){border-right:0}}
@media(max-width:620px){.v2-header .brand small{max-width:190px;white-space:normal}.v2-hero h1{font-size:clamp(45px,14vw,62px);letter-spacing:-2px}.v2-hero .actions{align-items:stretch;flex-direction:column}.v2-hero .primary,.v2-hero .secondary{text-align:center}.v2-hero .hero-media{min-height:330px}.v2-image-caption{left:24px;right:24px;bottom:22px}.v2-trust{justify-content:flex-start;padding:18px 24px;gap:13px}.v2-about,.v2-institutions{padding-left:22px;padding-right:22px}.v2-lead{font-size:30px}.v2-section-head h2{font-size:41px}.v2-institution,.v2-institution:nth-child(4),.v2-institution:nth-child(5){grid-column:span 12;border-right:0;min-height:250px}.v2-impact{padding:30px 22px;gap:0}.v2-impact>div{padding:18px 10px;gap:10px}.v2-impact strong{font-size:32px}.v2-impact span{font-size:10px}}
</style>
